 "Нет ответов.": [
  "No answers.",
  "Жауаптар жоқ."
 ],
 "Черновик": [
  "Draft",
  "Жоба"
 ],
 "Предложи для каждой недели цель, упражнения, время и проверяемый критерий успеха. Соблюдай бюджет. Единичную ошибку сначала перепроверь, не делай выводов о непроверенных темах. Не придумывай баллы или номера задач.": [
  "For each week suggest a goal, exercises, timing and a measurable success criterion. Respect the time budget. Recheck isolated errors. Do not infer untested skills or invent scores or problem numbers.",
  "Әр аптаға мақсат, жаттығу, уақыт және тексерілетін жетістік өлшемін ұсын. Уақыт шегін сақта. Бір реттік қатені қайта тексер. Тексерілмеген тақырыптар туралы қорытынды жасама, балл мен есеп нөмірлерін ойдан шығарма."
 ],
