 "Велосипедист движется со скоростью 2 м/с в течение 2 минут. Какой путь он проедет?": [
  "A cyclist rides at 2 m/s for 2 minutes. How far does the cyclist travel?",
  "Велосипедші 2 минут бойы 2 м/с жылдамдықпен жүрді. Қандай жол жүрді?"
 ],
 "Переводим 2 минуты в секунды: 2 · 60 = 120 с. При постоянной скорости s = vt = 2 · 120 = 240 м.": [
  "s = vt = 2 × 120 = 240 m.",
  "s = vt = 2 · 120 = 240 м."
 ],
 "Какое количество теплоты нужно для нагревания 2 кг воды на 5 °C? Удельная теплоёмкость воды 4200 Дж/(кг·°C).": [
  "How much heat warms 2 kg of water by 5 °C if c = 4200 J/(kg·°C)?",
  "2 кг суды 5 °C-қа қыздыруға қанша жылу керек? c = 4200 Дж/(кг·°C)."
 ],
 "По формуле Q = cmΔT получаем 4200 · 2 · 5 = 42000 Дж. Делим на 1000 для перевода в кДж.": [
  "Q = cmΔT = 4200 × 2 × 5 = 42 kJ.",
  "Q = cmΔT = 4200 · 2 · 5 = 42 кДж."
 ],
 "Тело массой 2 кг движется со скоростью 4 м/с. Определи его кинетическую энергию.": [
  "A 2 kg body moves at 4 m/s. Find its kinetic energy.",
  "Массасы 2 кг дененің жылдамдығы 4 м/с. Кинетикалық энергиясын тап."
 ],
 "Кинетическая энергия E = mv²/2. Подставляем E = 2 · 4²/2 = 16 Дж.": [
  "K = mv²/2 = 2 × 16/2 = 16 J.",
  "Eₖ = mv²/2 = 2 · 16/2 = 16 Дж."
 ],
 "Обогреватель мощностью 200 Вт включён на 30 минут. Сколько энергии он израсходует?": [
  "A 200 W heater runs for 30 minutes. How much energy does it use?",
  "Қуаты 200 Вт жылытқыш 30 минут жұмыс істеді. Қанша энергия жұмсалды?"
 ],
 "Мощность в киловаттах равна 0.2, время в часах — 0,5. Энергия E = Pt = 0.2 · 0,5 = 0.1 кВт·ч.": [
  "E = Pt = 0.2 × 0.5 = 0.1 kWh.",
  "E = Pt = 0.2 · 0,5 = 0.1 кВт·сағ."
 ],
 "Газу сообщили 180 Дж теплоты. Газ совершил работу 60 Дж. На сколько увеличилась внутренняя энергия?": [
  "A gas receives 180 J of heat and does 60 J of work. Find the increase in internal energy.",
  "Газ 180 Дж жылу алып, 60 Дж жұмыс атқарды. Ішкі энергияның өсімін тап."
 ],
 "Согласно первому закону термодинамики ΔU = Q − A. Вычитаем работу газа: 180 − 60 = 120 Дж.": [
  "ΔU = Q − W = 180 − 60 = 120 J.",
  "ΔU = Q − A = 180 − 60 = 120 Дж."
 ],
 "В первичной обмотке 600 витков, во вторичной 150. Первичное напряжение 40 В. Найди вторичное напряжение идеального трансформатора.": [
  "An ideal transformer has 600 primary turns, 150 secondary turns and 40 V input. Find the output voltage.",
  "Идеал трансформатордың бірінші орамында 600, екіншісінде 150 орам бар. Кіріс 40 В. Шығыс кернеуін тап."
 ],
 "Напряжения относятся как числа витков: U₂ = U₁ · 150/600. Это четверть входного напряжения: 40/4 = 10 В.": [
  "U₂ = U₁ × 150/600 = 10 V.",
  "U₂ = U₁ · 150/600 = 10 В."
 ],
 "Тележка массы m со скоростью 8 м/с сцепляется с неподвижной тележкой массы 3m. Сколько джоулей энергии движения останется, если m = 1 кг?": [
  "A cart of mass m travelling at 8 m/s sticks to a stationary cart of mass 3m. Find the remaining kinetic energy for m = 1 kg.",
  "m массалы арба 8 м/с жылдамдықпен 3m массалы тыныш арбаға тіркеледі. m = 1 кг болса, қалған кинетикалық энергия қандай?"
 ],
 "Импульс сохраняется: общая скорость v = 8/4 = 2 м/с. Общая масса 4 кг, поэтому E = 4 · 2²/2 = 8 Дж.": [
  "Momentum gives v = 8/4 = 2 m/s. K = 4v²/2 = 8 J.",
  "Импульс сақталады: v = 8/4 = 2 м/с. Eₖ = 4v²/2 = 8 Дж."
 ],
