 "Тележка массы m со скоростью 20 м/с сцепляется с неподвижной тележкой массы 3m. Сколько джоулей энергии движения останется, если m = 1 кг?": [
  "A cart of mass m travelling at 20 m/s sticks to a stationary cart of mass 3m. Find the remaining kinetic energy for m = 1 kg.",
  "m массалы арба 20 м/с жылдамдықпен 3m массалы тыныш арбаға тіркеледі. m = 1 кг болса, қалған кинетикалық энергия қандай?"
 ],
 "Импульс сохраняется: общая скорость v = 20/4 = 5 м/с. Общая масса 4 кг, поэтому E = 4 · 5²/2 = 50 Дж.": [
  "Momentum gives v = 20/4 = 5 m/s. K = 4v²/2 = 50 J.",
  "Импульс сақталады: v = 20/4 = 5 м/с. Eₖ = 4v²/2 = 50 Дж."
 ],
 "Велосипедист движется со скоростью 6 м/с в течение 2 минут. Какой путь он проедет?": [
  "A cyclist rides at 6 m/s for 2 minutes. How far does the cyclist travel?",
  "Велосипедші 2 минут бойы 6 м/с жылдамдықпен жүрді. Қандай жол жүрді?"
 ],
 "Переводим 2 минуты в секунды: 2 · 60 = 120 с. При постоянной скорости s = vt = 6 · 120 = 720 м.": [
  "s = vt = 6 × 120 = 720 m.",
  "s = vt = 6 · 120 = 720 м."
 ],
 "Какое количество теплоты нужно для нагревания 6 кг воды на 5 °C? Удельная теплоёмкость воды 4200 Дж/(кг·°C).": [
  "How much heat warms 6 kg of water by 5 °C if c = 4200 J/(kg·°C)?",
  "6 кг суды 5 °C-қа қыздыруға қанша жылу керек? c = 4200 Дж/(кг·°C)."
 ],
 "По формуле Q = cmΔT получаем 4200 · 6 · 5 = 126000 Дж. Делим на 1000 для перевода в кДж.": [
  "Q = cmΔT = 4200 × 6 × 5 = 126 kJ.",
  "Q = cmΔT = 4200 · 6 · 5 = 126 кДж."
 ],
 "Тело массой 6 кг движется со скоростью 4 м/с. Определи его кинетическую энергию.": [
  "A 6 kg body moves at 4 m/s. Find its kinetic energy.",
  "Массасы 6 кг дененің жылдамдығы 4 м/с. Кинетикалық энергиясын тап."
 ],
 "Кинетическая энергия E = mv²/2. Подставляем E = 6 · 4²/2 = 48 Дж.": [
  "K = mv²/2 = 6 × 16/2 = 48 J.",
  "Eₖ = mv²/2 = 6 · 16/2 = 48 Дж."
 ],
 "Обогреватель мощностью 600 Вт включён на 30 минут. Сколько энергии он израсходует?": [
  "A 600 W heater runs for 30 minutes. How much energy does it use?",
  "Қуаты 600 Вт жылытқыш 30 минут жұмыс істеді. Қанша энергия жұмсалды?"
 ],
 "Мощность в киловаттах равна 0.6, время в часах — 0,5. Энергия E = Pt = 0.6 · 0,5 = 0.3 кВт·ч.": [
  "E = Pt = 0.6 × 0.5 = 0.3 kWh.",
  "E = Pt = 0.6 · 0,5 = 0.3 кВт·сағ."
 ],
 "Газу сообщили 540 Дж теплоты. Газ совершил работу 180 Дж. На сколько увеличилась внутренняя энергия?": [
  "A gas receives 540 J of heat and does 180 J of work. Find the increase in internal energy.",
  "Газ 540 Дж жылу алып, 180 Дж жұмыс атқарды. Ішкі энергияның өсімін тап."
 ],
 "Согласно первому закону термодинамики ΔU = Q − A. Вычитаем работу газа: 540 − 180 = 360 Дж.": [
  "ΔU = Q − W = 540 − 180 = 360 J.",
  "ΔU = Q − A = 540 − 180 = 360 Дж."
 ],
 "В первичной обмотке 600 витков, во вторичной 150. Первичное напряжение 120 В. Найди вторичное напряжение идеального трансформатора.": [
  "An ideal transformer has 600 primary turns, 150 secondary turns and 120 V input. Find the output voltage.",
  "Идеал трансформатордың бірінші орамында 600, екіншісінде 150 орам бар. Кіріс 120 В. Шығыс кернеуін тап."
 ],
 "Напряжения относятся как числа витков: U₂ = U₁ · 150/600. Это четверть входного напряжения: 120/4 = 30 В.": [
  "U₂ = U₁ × 150/600 = 30 V.",
  "U₂ = U₁ · 150/600 = 30 В."
 ],
